import math

from queue import PriorityQueue

def knight_distance(n, start, goal, blocked):

    directions = [(-1, -2), (-2, -1), (1, -2), (2, -1), (-1, 2), (-2, 1), (1, 2), (2, 1)]

    def board_heuristic(pos):
            dr = abs(pos[0] - goal[0])
            dc = abs(pos[1] - goal[1])

            return max(math.ceil(dr / 2), math.ceil(dc / 2),
                       math.ceil((dr + dc) / 3))

    grid = [[0]*n for _ in range(n)]

    if (start[0], start[1]) in blocked or (goal[0], goal[1]) in blocked:
        return None

    priority_queue = PriorityQueue()
    visited_set = set()

    priority_queue.put((board_heuristic(start), start, [], 0))

    while not priority_queue.empty():
        curr_cost, curr_pos, curr_moves, curr_counter = priority_queue.get()
        if curr_pos in visited_set:
            continue

        visited_set.add(curr_pos)
        if curr_pos == goal:
            return len(curr_moves)

        for direction in directions:
            mod_row = direction[0]+curr_pos[0]
            mod_col = direction[1]+curr_pos[1]

            if 0<=mod_row<n and 0<=mod_col<n:
                if (mod_row, mod_col) in blocked:
                    continue

                a_star_calc = curr_cost - board_heuristic(curr_pos) + 1 + board_heuristic((mod_row, mod_col))
                priority_queue.put((a_star_calc, (mod_row, mod_col), curr_moves + [(mod_row, mod_col)], curr_counter+1))





    return None

