    if start in deadends or target in deadends:
        return []

    if start == target:
        return [[]]

    dead = set(deadends)
    directions = [-1, 1]

    def dfs_tree(curr_board, depth, moves):
        if depth == len(moves):
            if curr_board == target:
                solutions.append(moves)
            return
        curr_board_list = [int(char) for char in curr_board]
        for i in range(0, len(curr_board)):

            for direction in directions:

                digit = direction + curr_board_list[i]
                if digit == 10:
                    digit = 0
                if digit == -1:
                    digit = 9

                mod_board = "".join(map(str, curr_board_list[:i]
                                        + [digit]
                                        + curr_board_list[i + 1:]))
                if mod_board in dead:
                    continue

                dfs_tree(mod_board, depth, moves + [(i, direction)])

    limit = 1
    ceiling = 10 ** len(start)
    while limit <= ceiling:
        solutions = []
        dfs_tree(start, limit, [])
        if solutions:
            return solutions
        limit += 1

    return []

