def manhattan(board, goal):

    # formula: abs(row2-row1)+abs(col2-col1)
    distance = 0

    hashMap = {}

    for row in range(0, len(board)):
        for col in range(0, len(board[0])):
            curr_val_board = board[row][col]
            curr_val_goal = goal[row][col]

            if curr_val_board != 0:
                if curr_val_board not in hashMap:
                    hashMap[curr_val_board] = [(row, col)]
                else:
                    hashMap[curr_val_board].append((row, col))

            if curr_val_goal != 0:
                if curr_val_goal not in hashMap:
                    hashMap[curr_val_goal] = [(row, col)]
                else:
                    hashMap[curr_val_goal].append((row, col))

    for positions in hashMap.values():
        (row1, col1), (row2, col2) = positions
        distance += abs(row2-row1)+abs(col2-col1)

    return distance

