    rows, cols = len(board), len(board[0])

    tile = 1
    for row in range(rows):
        for col in range(cols):

            if row == rows-1 and col == cols-1:
                break
            if board[row][col] == 0:
                tile += 1
                continue
            if board[row][col] != tile:
                count += 1

            tile += 1

    if board[rows-1][cols-1] != 0:
        count += 1

    return count

