from queue import PriorityQueue

def cheapest_path(grid, start, goal):
    if grid[start[0]][start[1]] == 0 or grid[goal[0]][goal[1]] == 0:
        return None


    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, 1), (0, -1)]

    def board_heuristic(pos):
        row1, col1 = goal[0], goal[1]
        row2, col2 = pos[0], pos[1]

        return abs(row1-row2) + abs(col1-col2)

    priority_queue = PriorityQueue()
    visited_set = set()

    priority_queue.put((board_heuristic(start), start, [start], 0))

    while not priority_queue.empty():
        curr_cost, curr_pos, curr_moves, curr_counter = priority_queue.get()
        if curr_pos in visited_set:
            continue
        visited_set.add(curr_pos)
        if curr_pos == goal:
            return curr_moves

        for direction in directions:
            mod_row = direction[0]+curr_pos[0]
            mod_col = direction[1]+curr_pos[1]
            if 0<=mod_row<rows and 0<=mod_col<cols and grid[mod_row][mod_col] != 0:
                a_star_calc = curr_cost - board_heuristic(curr_pos) + grid[mod_row][mod_col] + board_heuristic((mod_row, mod_col))
                priority_queue.put((a_star_calc, (mod_row, mod_col), curr_moves + [(mod_row, mod_col)], curr_counter+1))

    return None
